import{_ as i,a0 as s,w as p,s as d,ao as n,I as o,x as t,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"4 款值得一试的 Linux 终端多路复用器 | LCTT x X-CMD","titleTemplate":false,"description":"4 款值得一试的 Linux 终端多路复用器 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 款值得一试的 Linux 终端多路复用器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 款值得一试的 Linux 终端多路复用器 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210512 4 Linux terminal multiplexers to try","title":"4 款值得一试的 Linux 终端多路复用器","tag":"202105","desc":""},"relativePath":"202105/20210512 4 Linux terminal multiplexers to try.md","filePath":"[post].md"}'),m={name:"202105/20210512 4 Linux terminal multiplexers to try.md"};function u(x,e,h,f,T,b){const r=s("Link");return p(),d("div",null,[e[28]||(e[28]=n('<h1 id="_4-款值得一试的-linux-终端多路复用器" tabindex="-1">4 款值得一试的 Linux 终端多路复用器 <a class="header-anchor" href="#_4-款值得一试的-linux-终端多路复用器" aria-label="Permalink to “4 款值得一试的 Linux 终端多路复用器”">​</a></h1><blockquote><p>比较 tmux、GNU Screen、Konsole 和 Terminator，看看哪个最适合你。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/24/205044ez55fdw99alhhgn8.jpg" alt=""></p><p>Linux 用户通常需要大量的虚拟视觉空间。一个终端窗口是永远不够的，所以终端有了标签。一个桌面太受限制了，所以有了虚拟桌面。当然，应用程序窗口可以堆叠，但当它们堆叠起来时，又有多大的好处呢？哎呀，即使是后台文本控制台也有 <code>F1</code> 到 <code>F7</code>，可以在任务之间来回翻转。</p><p>有了这么多的多任务处理方式，有人发明了终端 <em>多路复用器</em> 的概念就不奇怪了。诚然，这是一个令人困惑的术语。在传统的电子学中，“<ruby>多路复用器<rt>multiplexer</rt></ruby>”是一个接收多个输入信号并将选定的信号转发到单一输出的部件。终端多路复用器的作用正好相反。它从一个输入（人类在键盘上向一个终端窗口打字）接收指令，并将该输入转发给任意数量的输出（例如，一组服务器）。</p><p>然后，“多路复用器”一词在美国也是一个流行的术语，指的是有许多屏幕的电影院（与“<ruby>影城<rt>cineplex</rt></ruby>”一词一个意思）。在某种程度上，这很好地描述了终端复用器的作用。它可以在一个框内提供许多屏幕。</p><p>不管这个词是什么意思，任何尝试过它的人都有自己的喜好的某一种多路复用器。因此，我决定考察一些流行的终端多路复用器，看看每一个都怎么样。就我的评估标准而言，最低限度，我需要每个多路复用器能够分割<em>和</em>堆叠终端窗口。</p><h3 id="tmux" tabindex="-1">tmux <a class="header-anchor" href="#tmux" aria-label="Permalink to “tmux”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-tmux.png" alt="tmux" title="tmux"></p><p>据我所知，是从 tmux 开始使用“多路复用器”这个术语的。它工作的很出色。</p><p>它作为一个守护程序运行，这样即使你关闭了正在查看的终端模拟器，你的终端会话仍然处于活动状态。它将你的终端屏幕分割成多个面板，这样你就可以在每个面板上打开独特的终端提示符。</p><p>推而广之，这意味着你也可以远程连接到任何数量的系统，并在你的终端中打开它们。利用 tmux 的能力，将输入镜像（或者以电子学术语说是“反向多路复用”）到其他打开的窗格，就能从一个中央命令窗格同时控制几台计算机。</p><p>tmux 在 GNU Screen 还只能水平分割的时候就有了垂直分割能力，这吸引了追求最大灵活性的粉丝。而灵活性正是用户在 tmux 中得到的。它可以分割、堆叠、选择和提供服务；几乎没有什么是它做不到的。</p><h4 id="📦-软件包大小" tabindex="-1">📦 软件包大小 <a class="header-anchor" href="#📦-软件包大小" aria-label="Permalink to “📦 软件包大小”">​</a></h4><p>从软件包中安装 tmux 大约需要 700K，这还不算它所依赖的十几个共享库。</p><h4 id="🎛️-控制键" tabindex="-1">🎛️ 控制键 <a class="header-anchor" href="#🎛️-控制键" aria-label="Permalink to “🎛️ 控制键”">​</a></h4><p>tmux 的默认触发键是 <code>Ctrl+B</code>，尽管很容易在其配置文件中重新定义。</p><h4 id="⌨️-黑客因子" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>即使你只是在学习如何使用终端，你也一定会觉得使用 tmux 的人很像黑客。它看起来很复杂，但一旦你了解了正确的键绑定，就很容易使用。它为你提供了很多有用的技巧，让你玩的飞起，而且它是一种快速构建 HUD（抬头显示器）的超简单方法，可以把你需要的所有信息摆在你面前。</p><h3 id="gnu-screen" tabindex="-1">GNU Screen <a class="header-anchor" href="#gnu-screen" aria-label="Permalink to “GNU Screen”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-screen.png" alt="GNU Screen" title="GNU Screen"></p><p>像 tmux 一样，GNU Screen 也运行一个守护程序，所以即使你关闭了用来启动它的终端，你的 shell 仍然可用。你可以从不同的计算机上连接并共享屏幕。它可以将你的终端屏幕分割成水平或垂直的窗格。</p><p>与 tmux 不同的是，GNU Screen 可以通过串行连接进行连接（<code>screen 9600 /dev/ttyUSB0</code> 就可以了），通过按键绑定可以方便地发出 <code>XON</code> 和 <code>XOFF</code> 信号。</p>',23)),o("p",null,[e[1]||(e[1]=t("与 SSH 会话相比，在串行连接中需要多路复用器的情况可能并不常见，所以大多数用户并不了解 Screen 这个真正特殊的功能。不过，GNU Screen 是一个很棒的多路复用器，有很多有用的选项。而如果你真的需要同时向多个服务器发送信号，还有专门的工具，比如 ClusterSSH 和 ",-1)),a(r,{href:"https://opensource.com/article/19/2/quickstart-guide-ansible"},{default:l(()=>[...e[0]||(e[0]=[t("Ansible",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[29]||(e[29]=n('<h4 id="📦-软件包大小-1" tabindex="-1">📦 软件包大小 <a class="header-anchor" href="#📦-软件包大小-1" aria-label="Permalink to “📦 软件包大小”">​</a></h4><p>从软件包中安装 GNU Screen 大约需要 970K，这还不算它所依赖的十几个共享库。</p><h4 id="🎛️-控制键-1" tabindex="-1">🎛️ 控制键 <a class="header-anchor" href="#🎛️-控制键-1" aria-label="Permalink to “🎛️ 控制键”">​</a></h4><p>GNU Screen 的默认触发键是 <code>Ctrl+A</code>，这对于熟悉 Bash 快捷键的人来说可能特别烦人。幸运的是，你可以在配置文件中轻松地重新定义这个触发键。</p><h4 id="⌨️-黑客因子-1" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子-1" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>当使用 Screen 通过串行连接到你的路由器或你的原型电路板时，你会成为你所有硬件黑客朋友羡慕的对象。</p><h3 id="konsole" tabindex="-1">Konsole <a class="header-anchor" href="#konsole" aria-label="Permalink to “Konsole”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-konsole.png" alt="Konsole" title="Konsole"></p><p>对于没有标榜自己是多路复用器的 Konsole 来说，令人惊讶的是它也是其中一个。它可以使用 Qt 窗格和标签进行必要的窗口分割和堆叠，但它也可以通过“编辑（将输入复制到）”菜单中的一个选项将输入从一个窗格传到另一个（或全部）。</p>',9)),o("p",null,[e[5]||(e[5]=t("然而，它所最明显缺乏的功能是作为一个守护程序运行以进行远程重新连接的能力。与 tmux 和 GNU Screen 不同，你不能远程连接到运行 Konsole 的机器并加入会话。对于一些管理员来说，这可能不是一个问题。许多管理员用 ",-1)),a(r,{href:"https://en.wikipedia.org/wiki/Virtual_Network_Computing"},{default:l(()=>[...e[3]||(e[3]=[t("VNC",-1)])]),_:1}),e[6]||(e[6]=t(" 连接到机器的次数比用 ",-1)),a(r,{href:"https://en.wikipedia.org/wiki/Secure_Shell_Protocol"},{default:l(()=>[...e[4]||(e[4]=[t("SSH",-1)])]),_:1}),e[7]||(e[7]=t(" 还要多，所以“重新加入”一个会话就像在 VNC 客户端上点击 Konsole 窗口一样简单。",-1))]),o("p",null,[e[9]||(e[9]=t("使用 Konsole 作为多路复用器是 KDE 极客们的大招。Konsole 是我使用的第一个 Linux 终端（直到今天，我有时也会按 ",-1)),e[10]||(e[10]=o("code",null,"Ctrl+N",-1)),e[11]||(e[11]=t(" 来切换新标签），所以有能力使用这个熟悉的终端作为多路复用器是一个很大的便利。这绝不是必要的，因为无论如何 tmux 和 Screen 都可以在 Konsole 里面运行，但是通过让 Konsole 处理窗格，我就不必调整肌肉记忆。这种微妙的功能包容正是 ",-1)),a(r,{href:"https://opensource.com/article/19/12/linux-kde-plasma"},{default:l(()=>[...e[8]||(e[8]=[t("KDE 的伟大之处",-1)])]),_:1}),e[12]||(e[12]=t("。",-1))]),e[30]||(e[30]=n('<h4 id="📦-软件包大小-2" tabindex="-1">📦 软件包大小 <a class="header-anchor" href="#📦-软件包大小-2" aria-label="Permalink to “📦 软件包大小”">​</a></h4><p>Konsole 本身大约是 11KB，但它依赖于 105 个 KDE 和 Qt 库，所以实际上，它至少有 50MB。</p><h4 id="🎛️-控制键-2" tabindex="-1">🎛️ 控制键 <a class="header-anchor" href="#🎛️-控制键-2" aria-label="Permalink to “🎛️ 控制键”">​</a></h4><p>大多数重要的 Konsole 快捷键以 <code>Shift+Ctrl</code> 开始，分割屏幕、打开新标签、复制输入到其他窗格等都是如此。这是 KDE 里的主控台，所以如果你对 Plasma 桌面很熟悉，会感觉快捷键很熟悉。</p><h4 id="⌨️-黑客因子-2" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子-2" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>使用 Konsole 作为你的多路复用器让你有资格称自己为 KDE 高级用户。</p><h3 id="terminator" tabindex="-1">Terminator <a class="header-anchor" href="#terminator" aria-label="Permalink to “Terminator”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-terminator.png" alt="Terminator" title="Terminator"></p><p>对于 GNOME 用户来说，Terminator 多路复用器是为他们原本极简的 GNOME 终端增加功能的一个简单方法。除了必要的多路复用功能外，Terminator 还可以向所有打开的窗格广播输入，但和 Konsole 一样，它不会在后台运行以便你可以通过 SSH 重新连接到它。话说回来，由于 GNOME 和 Wayland 让 VNC 变得如此简单，你有可能会觉得没有必要通过 SSH 来恢复终端会话。</p><p>如果你愿意，Terminator 可以完全由鼠标驱动。Konsole 通过其主菜单也有同样的能力。有了 Terminator，你可以在 Shell 的任何地方点击右键，弹出相关选项，以水平或垂直分割窗口，将窗格分组作为广播目标，广播输入，关闭窗格，等等。你还可以为所有这些动作配置键盘快捷键，所以在许多方面，你可以形成自己的体验。</p><p>我认为自己主要是一个 KDE 用户，所以当我说 Terminator 感觉像一个 KDE 应用时，我其实是一种极大的赞美。Terminator 是一个令人惊讶的可配置的和灵活的应用程序。在许多方面，它体现了开源的力量，把简陋的 GNOME 终端变成了一个强大的多路复用器。</p><h4 id="📦-软件包大小-3" tabindex="-1">📦 软件包大小 <a class="header-anchor" href="#📦-软件包大小-3" aria-label="Permalink to “📦 软件包大小”">​</a></h4><p>Terminator 的安装容量为 2.2MB，其中大部分是 Python 模块。但它依赖于 GTK3 和 GNOME，所以如果你没有运行完整的 GNOME 桌面，可以预料你需要一个更大的安装来拉入这些依赖。</p><h4 id="🎛️-控制键-3" tabindex="-1">🎛️ 控制键 <a class="header-anchor" href="#🎛️-控制键-3" aria-label="Permalink to “🎛️ 控制键”">​</a></h4><p>Terminator 的默认控制键没有什么一致性。你可以用 <code>Alt</code> 键来执行一些命令，用 <code>Ctrl</code> 来执行其他命令，还可以用 <code>Shift+Ctrl</code>、<code>Ctrl+Alt</code>、<code>Shift+Super</code> 等等，还有鼠标。话说回来，这是我试过的最可配置的多路复用器之一，所以只要有想法，稍加努力，你就能设计出适合你的模式。</p><h4 id="⌨️-黑客因子-3" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子-3" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>当你使用 Terminator 时，你会觉得自己是最现代、最务实的黑客。由于它的各种极客选项，它是多路复用的最佳选择，而且由于它非常灵活，无论你的手是在键盘上，还是键盘和鼠标并用，你都可以同样轻松地使用它。</p><h3 id="我全要" tabindex="-1">我全要 <a class="header-anchor" href="#我全要" aria-label="Permalink to “我全要”">​</a></h3><p>还有更多的多路复用器和一些具有类似多路复用能力的应用。你不必非要找到<em>一个</em>完全按照你想要的方式完成你需要的所有工作的多路复用器。你可以使用不止一个。事实上，你甚至可以同时使用多个，因为 tmux 和 Screen 实际上是 shell，而 Konsole 和 Terminator 是显示 shell 的终端。对唾手可得的工具感到舒适，而且它们能帮助你管理你的工作空间，使你能有效地工作，才是最重要的。</p><p>去尝试一下多路复用器，或者在你喜欢的应用程序中发现类似多路复用器的功能。它可能会改变你看待计算的方式。</p><hr>',21)),o("p",null,[e[14]||(e[14]=t("via: ",-1)),a(r,{href:"https://opensource.com/article/21/5/linux-terminal-multiplexer"},{default:l(()=>[...e[13]||(e[13]=[t("https://opensource.com/article/21/5/linux-terminal-multiplexer",-1)])]),_:1})]),o("p",null,[e[19]||(e[19]=t("作者：",-1)),a(r,{href:"https://opensource.com/users/seth"},{default:l(()=>[...e[15]||(e[15]=[t("Seth Kenlon",-1)])]),_:1}),e[20]||(e[20]=t(" 选题：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[16]||(e[16]=[t("lujun9972",-1)])]),_:1}),e[21]||(e[21]=t(" 译者：",-1)),a(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1}),e[22]||(e[22]=t(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[18]||(e[18]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[25]||(e[25]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[23]||(e[23]=[t("LCTT",-1)])]),_:1}),e[26]||(e[26]=t(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:l(()=>[...e[24]||(e[24]=[t("Linux中国",-1)])]),_:1}),e[27]||(e[27]=t(" 荣誉推出",-1))])])}const N=i(m,[["render",u]]);export{C as __pageData,N as default};
